export default function progress({ events, previousState, uploadId, uploadName, uploadType }) {
  if (!Array.isArray(events)) throw new Error("Expected Drive event batch");
  let index = 0,
    completed = [];
  if (previousState != null) {
    if (
      !Number.isInteger(previousState.index) ||
      !Array.isArray(previousState.completed) ||
      previousState.index < 1 ||
      previousState.index > events.length ||
      previousState.completed.length !== previousState.index - 1
    )
      throw new Error("Invalid progress");
    if (
      typeof uploadId !== "string" ||
      !uploadId ||
      typeof uploadName !== "string" ||
      uploadType !== "image/png"
    )
      throw new Error("Drive did not confirm the PNG; inspect before replaying");
    index = previousState.index;
    completed = [
      ...previousState.completed,
      { inputId: events[index - 1].fileId, outputId: uploadId, name: uploadName },
    ];
  }
  const event = events[index];
  if (!event)
    return { state: { index, completed }, more: false, fileId: "none", count: completed.length };
  if (
    event.eventType !== "file_created" ||
    event.itemType !== "file" ||
    typeof event.fileId !== "string" ||
    !event.fileId
  )
    throw new Error("Invalid Drive event");
  return {
    state: { index: index + 1, completed },
    more: true,
    fileId: event.fileId,
    count: completed.length,
  };
}

