export default function inputFile({ file, expectedId, metadata, statusCode }) {
  if (
    file?.fileId !== expectedId ||
    typeof file.name !== "string" ||
    typeof file.transitUrl !== "string" ||
    !file.transitUrl.startsWith("https://") ||
    statusCode !== 200 ||
    metadata?.id !== expectedId ||
    typeof metadata.originalFilename !== "string"
  )
    throw new Error("Drive download or original filename not confirmed");
  return {
    url: file.transitUrl,
    name: "BG-Removed-" + metadata.originalFilename.split(".").slice(0, -1).join(".") + ".png",
  };
}

