export default function options({ metadata, keepInputSize, width, height, padding }) {
  const w = keepInputSize ? metadata?.width : width,
    h = keepInputSize ? metadata?.height : height;
  if (
    !Number.isSafeInteger(w) ||
    w < 1 ||
    !Number.isSafeInteger(h) ||
    h < 1 ||
    typeof padding !== "number" ||
    padding < 0 ||
    padding >= 0.5
  )
    throw new Error("Invalid image size or edit settings");
  return { canvas: { width: w, height: h, padding } };
}

