import { Buffer } from "node:buffer";
export default async function imageBytes({ url, size, contentType }, context) {
  if (
    contentType !== "image/png" ||
    !Number.isSafeInteger(size) ||
    size < 1 ||
    typeof url !== "string" ||
    !url.startsWith("https://")
  )
    throw new Error("Photoroom did not return a PNG");
  const response = await context.fetch(url, { method: "GET" });
  if (!response.ok) throw new Error("PNG download failed");
  const b = new Uint8Array(await response.arrayBuffer());
  if (b.length !== size) throw new Error("Incomplete PNG");
  return { contentBase64: Buffer.from(b).toString("base64") };
}
